```python
import re
import sys
from collections import defaultdict

FLAKY_HINTS = [
    "ECONNRESET",
    "ETIMEDOUT",
    "Temporary failure in name resolution",
    "429 Too Many Requests",
]


def classify(code):
    if code == 0:
        return "ok"
    elif code >= 1 and code <= 2:
        return "failed"
    elif code == 124:
        return "timeout"
    elif code >= 126 and code <= 127:
        return "not_found"
    elif code > 128 and code < 160 and (code - 128) in (9, 15):
        return "killed"
    elif code > 128 and code < 160 and (code - 128) == 2:
        return "interrupted"
    elif code > 128:
        return "signal"
    else:
        return "failed"


def is_flaky(msg):
    for hint in FLAKY_HINTS:
        if re.search(re.escape(hint), msg, re.IGNORECASE):
            return True
    return False


def summarize(lines):
    counts = defaultdict(int)
    flaky = 0
    for line in lines:
        m = re.match(r"^(\S+) \[(\w+)\] exit=(\d+) (.*)$", line.rstrip("\n"))
        if not m:
            continue
        ts, stage, code, msg = m.groups()
        kind = classify(int(code))
        counts[(stage, kind)] += 1
        if kind != "ok" and is_flaky(msg):
            flaky += 1
    return dict(sorted(counts.items())), flaky


if __name__ == "__main__":
    result, flaky = summarize(sys.stdin)
    for (stage, kind), n in result.items():
        print(f"{stage:10} {kind:12} {n}")
    print("flaky:", flaky)
